# Minimal implementation of the core JAX transformation method
# that defines primitives, tracers, and interpreters, along with a
# simple forward-mode automatic differentiation (JVP) transformation.

from typing import NamedTuple

# -----------------------------------------------------------------------------
# Primitive definition: each primitive is represented by a name.

class Primitive(NamedTuple):
    name: str

# User-facing functions use a binder to dispatch to the current trace.

def add(x, y):
    return bind(Primitive('add'), x, y)


def mul(x, y):
    return bind(Primitive('mul'), x, y)

# -----------------------------------------------------------------------------
# Base classes for implementing interpreters and tracing (Traces and Tracers).

class Trace:
    def pure(self, val):
        raise NotImplementedError()

    def lift(self, val):
        raise NotImplementedError()

    def process_primitive(self, primitive, tracers, params):
        raise NotImplementedError()


class Tracer:
    def __init__(self, trace, val):
        self._trace = trace
        self.val = val

    def __add__(self, other):
        return add(self, other)

    def __mul__(self, other):
        return mul(self, other)

# Global variable representing the current trace (interpreter).
# Initially, we use a simple evaluation trace.

class EvalTrace(Trace):
    def pure(self, val):
        return val

    def lift(self, val):
        return val

    def process_primitive(self, primitive, tracers, params):
        # Unbox any tracers to obtain their values
        unboxed = [t if not isinstance(t, Tracer) else t.val for t in tracers]
        if primitive.name == 'add':
            return sum(unboxed)
        elif primitive.name == 'mul':
            prod = 1
            for x in unboxed:
                prod *= x
            return prod
        else:
            raise ValueError(f'Unknown primitive: {primitive}')

# The default evaluation trace
current_trace = EvalTrace()

# Binder function that routes primitive applications to the current trace.

def bind(prim, *args, **params):
    return current_trace.process_primitive(prim, args, params)

# -----------------------------------------------------------------------------
# Implementation of forward-mode autodifferentiation (JVP transformation).

# A tracer for JVP that carries both a primal and tangent (derivative) value.

class JVPTracer(Tracer):
    def __init__(self, trace, primal, tangent):
        super().__init__(trace, primal)
        self.primal = primal
        self.tangent = tangent

# A JVP interpreter that defines how to propagate dual (primal/tangent) values
# through primitive operations.

class JVPTrace(Trace):
    def pure(self, val):
        return JVPTracer(self, val, 0)

    def lift(self, val):
        return JVPTracer(self, val, 0)

    def process_primitive(self, primitive, tracers, params):
        primals = [t.primal for t in tracers]
        tangents = [t.tangent for t in tracers]
        if primitive.name == 'add':
            result_primal = sum(primals)
            result_tangent = sum(tangents)
            return JVPTracer(self, result_primal, result_tangent)
        elif primitive.name == 'mul':
            a, b = primals
            a_dot, b_dot = tangents
            result_primal = a * b
            result_tangent = a * b_dot + a_dot * b
            return JVPTracer(self, result_primal, result_tangent)
        else:
            raise ValueError(f'Unknown primitive in JVP: {primitive}')

# The JVP transformation function, which takes a function f, along with input
# primals and tangents, and returns the primal output and its tangent.

def jvp_v1(f, primals, tangents):
    # Create a JVP trace and convert every input into a JVPTracer.
    jvp_trace = JVPTrace()
    tracers_in = [JVPTracer(jvp_trace, p, t) for p, t in zip(primals, tangents)]
    out = f(*tracers_in)
    # Assume the output is a JVPTracer and extract its components.
    return out.primal, out.tangent

# -----------------------------------------------------------------------------
# Example usage:

# Define a simple function using the primitives.

def foo(x):
    # Computes: x * (x + 3.0)
    return mul(x, add(x, 3.0))

# Evaluate the function at a concrete value with forward-mode AD to compute its
# derivative. For example, at x = 2.0 with tangent 1.0 (differentiating with respect
# to x):

primal_out, tangent_out = jvp_v1(foo, (2.0,), (1.0,))

print(f'foo(2.0) = {primal_out}, derivative = {tangent_out}')
